from datetime import date

TODAY = date(2026,10,12)
REG   = date(2026,8,12)   # negativação Serasa
RECON = date(2022,9,15)   # e-mail reconhecimento parcelas 1-4
PAY   = date(2023,8,2)    # PIX 10.000 na parcela 1

def add_years(d, n):
    try: return d.replace(year=d.year+n)
    except ValueError: return d.replace(month=2, day=28, year=d.year+n)

parcelas = {1:date(2020,10,10),2:date(2020,11,10),3:date(2020,12,10),
            4:date(2021,1,10),5:date(2021,2,10),6:date(2021,3,10)}
reconhecidas = {1,2,3,4}

print("parcela | vencimento | termo 5a (sem interrupção) | interrompida_em | novo termo (5a do ato) | prescrita hoje?")
for p,v in parcelas.items():
    termo = add_years(v,5)
    if p in reconhecidas and v < RECON < termo:
        novo = add_years(RECON,5)
        print(f"{p} | {v} | {termo} | {RECON} | {novo} | NAO (prescreve em {novo}) | meses restantes: {(novo-TODAY).days/30.44:.1f}")
    else:
        print(f"{p} | {v} | {termo} | — | — | {'SIM' if TODAY >= termo else 'NAO'} | dias desde o termo: {(TODAY-termo).days}")
